pub const parse_table_static_bytes =
    @sizeOf(@TypeOf(symbols)) +
    @sizeOf(@TypeOf(production_rhs)) +
    @sizeOf(@TypeOf(productions)) +
    @sizeOf(@TypeOf(state_items)) +
    @sizeOf(@TypeOf(states)) +
    @sizeOf(@TypeOf(actions)) +
